package com.yuegang.zhihui.search.application;
import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.search.api.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.client.RestClient;
public final class IndexLifecycleService{private final JdbcTemplate jdbc;private final RestClient elastic;private final String alias;public IndexLifecycleService(JdbcTemplate jdbc,String elasticBase,String alias){this.jdbc=jdbc;elastic=RestClient.builder().baseUrl(elasticBase).build();this.alias=alias;}public IndexVersionView status(){return jdbc.query("SELECT alias_name,active_version,previous_version,switched_at,(SELECT COUNT(*) FROM search_embedding e WHERE e.index_version=v.active_version) FROM search_index_version v WHERE alias_name=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new IndexVersionView(r.getString(1),r.getString(2),r.getString(3),r.getLong(5),r.getTimestamp(4).toLocalDateTime().atOffset(ZoneOffset.UTC));},alias);}public void create(String version){valid(version);var properties=new LinkedHashMap<String,Object>();properties.put("documentId",Map.of("type","keyword"));properties.put("chunkId",Map.of("type","keyword"));properties.put("title",Map.of("type","text"));properties.put("content",Map.of("type","text"));properties.put("category",Map.of("type","keyword"));properties.put("visibility",Map.of("type","keyword"));properties.put("documentVersion",Map.of("type","long"));properties.put("sourceUpdatedAt",Map.of("type","date"));elastic.put().uri("/"+version).body(Map.of("mappings",Map.of("properties",properties))).retrieve().toBodilessEntity();}public IndexVersionView switchTo(SwitchIndexRequest command){valid(command.version());Long count=jdbc.queryForObject("SELECT COUNT(*) FROM search_embedding WHERE index_version=?",Long.class,command.version());if(count==null||count<1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);var body=Map.of("actions",List.of(Map.of("remove",Map.of("index","*","alias",alias,"must_exist",false)),Map.of("add",Map.of("index",command.version(),"alias",alias))));elastic.post().uri("/_aliases").body(body).retrieve().toBodilessEntity();if(jdbc.update("UPDATE search_index_version SET previous_version=active_version,active_version=?,switched_at=NOW() WHERE alias_name=?",command.version(),alias)!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return status();}public void deletePrevious(){var status=status();if(status.previousVersion()==null)return;if(status.previousVersion().equals(status.activeVersion()))throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);elastic.delete().uri("/"+status.previousVersion()).retrieve().toBodilessEntity();jdbc.update("DELETE FROM search_embedding WHERE index_version=?",status.previousVersion());jdbc.update("UPDATE search_index_version SET previous_version=NULL WHERE alias_name=?",alias);}private static void valid(String value){if(value==null||!value.matches("[a-z0-9][a-z0-9._-]{1,63}"))throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}
